// --- CONFIGURAÇÃO MESTRE: Yamar (com Profissional Fallback) ---
const body = $input.item.json.body || $input.item.json;
const idAtendimento = body.id_atendimento || body.atendimento_id || body.session_id || body.sessionId || '';
const telefoneRaw = body.telefone_cliente || body.telefone_contato || body.telefone || '';
const telefoneLimpo = telefoneRaw.toString().replace(/\D/g, '');
const nomePaciente = body.nome_cliente || body.nome_contato || 'Paciente';
const insistiu = body.insistiu === true || body.insistiu === 'true';
const periodo = (body.periodo || body.horario_preferido || '').toString().toLowerCase();
const TIMEZONE = 'America/Sao_Paulo';
// ── Unidade única ──────────────────────────────────────
const unidadeChave = 'yamar';
// ── Configurações por unidade ──────────────────────────────────
const CONFIGS = {
  yamar: {
    subscriber_id:            '6091062965829632',
    business_id:              '6091062965829632',
    nome_unidade:             'Yamar',
    nome_empresa:             'Yamar',
    link_agenda:              '177299',
    duracao_servico:          45,
    capacidade_simultanea:    2,
    timezone:                 TIMEZONE,
    limite_dias_busca_normal: 10,
    profissional:          { id: '5776471249977344', nome: 'Pauline Louise de Melo Oberg e Silva' },
    profissional_fallback: { id: '6282863807823873', nome: 'Camila Rado Belmonte' },
    authorization: 'Basic ' + Buffer.from('yamar:513b819a-fa96-4c40-94da-0e2ff08a6511').toString('base64')
  },
};
const CONFIG = CONFIGS[unidadeChave];
// ── Parse de datas — aceita ISO completo e destrincha data + hora ──
const hoje       = DateTime.now().setZone(TIMEZONE);
const dataInicio = hoje.toFormat('yyyy-MM-dd');
const dataRaw = body.data_iso || body.data_inicio || body.data_agendada || '';
let dtP = null;
if (dataRaw) {
  dtP = DateTime.fromISO(dataRaw, { zone: TIMEZONE });
  if (!dtP.isValid) dtP = DateTime.fromFormat(dataRaw, 'yyyy-MM-dd HH:mm', { zone: TIMEZONE });
  if (!dtP.isValid) dtP = DateTime.fromFormat(dataRaw, 'dd/MM/yyyy HH:mm', { zone: TIMEZONE });
}
// hora embutida no ISO (ex: "2026-03-11T14:00:00")
const horaDoISO = (dtP && dtP.isValid && (dtP.hour > 0 || dtP.minute > 0))
  ? dtP.toFormat('HH:mm') : '';
// prioridade: horario_agendado > horario > hora do ISO
const horaFinal = (body.horario_agendado && body.horario_agendado.length >= 4)
  ? body.horario_agendado
  : (body.horario && body.horario.length >= 4)
  ? body.horario
  : horaDoISO;
const dataFinal = (dtP && dtP.isValid) ? dtP.toFormat('yyyy-MM-dd') : '';
const dataFim   = (dtP && dtP.isValid)
  ? dtP.plus({ days: 7 }).toFormat('yyyy-MM-dd')
  : hoje.plus({ days: 7 }).toFormat('yyyy-MM-dd');
return {
  json: {
    acao_fluxo:        body.action || body.acao_fluxo,
    id_atendimento:    idAtendimento,
    helena_company_id: '9c12ee45-64f9-4a1e-9353-7fea72e5fc5f',
    periodo:           periodo,
    nome_paciente:     nomePaciente,
    telefone_limpo:    telefoneLimpo,
    insistiu:          insistiu,
    data_nascimento:   body.data_nascimento || '',
    data_inicio:       dataInicio,
    data_agendada:     dataFinal,
    data_antiga:       body.data_antiga || body['data-antiga'] || '',
    data_fim:          dataFim,
    horario_agendado:  horaFinal,
    config_agenda: {
      subscriber_id:            CONFIG.subscriber_id,
      business_id:              CONFIG.business_id,
      nome_unidade:             CONFIG.nome_unidade,
      nome_empresa:             CONFIG.nome_empresa,
      link_agenda:              CONFIG.link_agenda,
      duracao_servico:          CONFIG.duracao_servico,
      capacidade_simultanea:    CONFIG.capacidade_simultanea,
      timezone:                 CONFIG.timezone,
      limite_dias_busca_normal: CONFIG.limite_dias_busca_normal,
      profissional:             CONFIG.profissional,
      profissional_fallback:    CONFIG.profissional_fallback,
      authorization:            CONFIG.authorization
    }
  }
};

// =============================================================
// LÓGICA INTELIGENTE — Yamar (multi-day)
// Principal: Pauline Louise de Melo Oberg e Silva | Fallback: Camila Rado Belmonte
// REGRA: máximo 2 opções sempre.
// O prompt já pergunta o período antes de chamar esta habilidade.
//
// REGRA DE FALLBACK (mesmo padrão do Oral Bem Joinville):
//   Os slots do principal e do fallback são unificados em
//   `todosBlocos`, com o principal entrando primeiro no array —
//   isso garante que, ao deduplicar por (data + horário), o slot
//   do principal sempre "vence" quando os dois têm o mesmo horário
//   livre. O fallback só aparece quando o principal não tem aquele
//   horário específico disponível.
// =============================================================

// ── 1. CONFIGURAÇÃO ───────────────────────────────────────────
const cfgNode = $('Configuracao Unidades').first().json;
const ca = cfgNode.config_agenda || {};

const TIMEZONE    = ca.timezone || 'America/Sao_Paulo';
const LIMITE_DIAS = ca.limite_dias_busca_normal || 7;

const PROF_PRINCIPAL = {
  id:   String(ca.profissional?.id || ''),
  nome: ca.profissional?.nome || 'Profissional'
};
const PROF_FALLBACK = {
  id:   String(ca.profissional_fallback?.id || ''),
  nome: ca.profissional_fallback?.nome || ''
};

// ── 2. INPUT ──────────────────────────────────────────────────
const diasAPI = $input.all().map(i => i.json);

// ── 3. DADOS DO PEDIDO ────────────────────────────────────────
const insistiu = cfgNode.insistiu === true;
const hRaw     = cfgNode.horario_agendado || '';
const dRaw     = cfgNode.data_agendada   || '';
const agora    = DateTime.now().setZone(TIMEZONE);

// Período: 'manha' | 'tarde' | '' — sempre informado pelo prompt antes desta chamada
const periodoRaw = (cfgNode.periodo || '').toString().toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const PERIODO       = (periodoRaw === 'manha' || periodoRaw === 'tarde') ? periodoRaw : '';
const PERIODO_LABEL = PERIODO === 'manha' ? 'manhã' : 'tarde';

let dtSolicitado = null;
if (dRaw && hRaw) {
  dtSolicitado = DateTime.fromFormat(`${dRaw} ${hRaw}`, 'yyyy-MM-dd HH:mm', { zone: TIMEZONE });
} else if (dRaw) {
  dtSolicitado = DateTime.fromFormat(dRaw, 'yyyy-MM-dd', { zone: TIMEZONE });
}

let diffDias = 0, bloqueado = false;
if (dtSolicitado?.isValid) {
  diffDias = dtSolicitado.startOf('day').diff(agora.startOf('day'), 'days').days;
  if (diffDias > LIMITE_DIAS && !insistiu) bloqueado = true;
}

// ── 4. HELPERS ────────────────────────────────────────────────
function horaParaMin(str) {
  if (!str) return -1;
  const p = str.split(':');
  return parseInt(p[0]) * 60 + parseInt(p[1] || '0');
}

const ehManha = b => b.minutos < 720;
const ehTarde = b => b.minutos >= 720;

const ordenar = arr => [...arr].sort((a, b) =>
  a.data === b.data ? a.minutos - b.minutos : (a.data < b.data ? -1 : 1));

// Retorna no máximo 2 vagas do período informado (ou qualquer período se vazio)
function opcoesDoPeriodo(blocos, fallback) {
  // Com período definido: as 2 vagas mais próximas daquele período
  if (PERIODO) {
    const filtro = PERIODO === 'manha' ? ehManha : ehTarde;
    const candidatos = ordenar(blocos.filter(filtro));
    if (candidatos.length > 0) return candidatos.slice(0, 2);
    // Período esgotado — oferece o oposto
    const outro = PERIODO === 'manha' ? ehTarde : ehManha;
    const base = fallback || blocos;
    return ordenar(base.filter(outro)).slice(0, 2);
  }
  // Sem período: 1 manhã + 1 tarde
  // Se o dia específico não tiver um dos turnos, busca no fallback (todos os dias)
  const base = fallback || blocos;
  const manha = ordenar(blocos.filter(ehManha)).slice(0, 1).length > 0
    ? ordenar(blocos.filter(ehManha)).slice(0, 1)
    : ordenar(base.filter(ehManha)).slice(0, 1);
  const tarde = ordenar(blocos.filter(ehTarde)).slice(0, 1).length > 0
    ? ordenar(blocos.filter(ehTarde)).slice(0, 1)
    : ordenar(base.filter(ehTarde)).slice(0, 1);
  const opcoes = ordenar([...manha, ...tarde]);
  return opcoes.length > 0 ? opcoes : ordenar(base).slice(0, 2);
}

// Horário específico indisponível: 1 antes + 1 depois no mesmo dia (max 2)
function vizinhos(blocosDia, minAlvo) {
  const antes  = ordenar(blocosDia).filter(b => b.minutos < minAlvo).pop();
  const depois = ordenar(blocosDia).find(b => b.minutos > minAlvo);
  return [antes, depois].filter(Boolean).slice(0, 2);
}

// ── 5. PROCESSAR UM DIA (separa slots do principal e do fallback) ──
function processarDia(dia) {
  const slots = (dia.AvaliableTimes || []).filter(s => s.isSelectable !== false);
  const principal = [];
  const fallback  = [];
  for (const slot of slots) {
    const sid = String(slot.professionalId);
    const bloco = {
      data:        dia.jsonDate,
      semana:      dia.Week,
      minutos:     horaParaMin(slot.from),
      horario:     slot.from,
      horario_fim: slot.to
    };
    if (sid === PROF_PRINCIPAL.id) {
      principal.push({ ...bloco, profId: PROF_PRINCIPAL.id, profNome: PROF_PRINCIPAL.nome });
    } else if (PROF_FALLBACK.id && sid === PROF_FALLBACK.id) {
      fallback.push({ ...bloco, profId: PROF_FALLBACK.id, profNome: PROF_FALLBACK.nome });
    }
  }
  return {
    principal: principal.sort((a, b) => a.minutos - b.minutos),
    fallback:  fallback.sort((a, b) => a.minutos - b.minutos)
  };
}

// ── 6. TODOS OS BLOCOS (principal primeiro, fallback preenche as lacunas) ──
let blocosPrincipal = [];
let blocosFallback  = [];
for (const dia of diasAPI) {
  const { principal, fallback } = processarDia(dia);
  blocosPrincipal = blocosPrincipal.concat(principal);
  blocosFallback  = blocosFallback.concat(fallback);
}

const usandoFallback = blocosPrincipal.length === 0 && blocosFallback.length > 0;

// Principal entra primeiro no array: garante prioridade dele na deduplicação
const vistos = new Set();
let todosBlocos = blocosPrincipal.concat(blocosFallback).filter(b => {
  const chave = `${b.data}_${b.horario}`;
  if (vistos.has(chave)) return false;
  vistos.add(chave);
  return true;
});

// ── 7. FORMATAÇÃO ─────────────────────────────────────────────
const fmtBloco = b => {
  const [yyyy, mm, dd] = b.data.split('-');
  const turno = ehManha(b) ? 'manhã' : 'tarde';
  return `🗓️ *${dd}/${mm} (${b.semana})* às *${b.horario}* – *${b.horario_fim}* (${turno}) com ${b.profNome}`;
};

const dtLabel = dtSolicitado?.isValid
  ? dtSolicitado.setLocale('pt-BR').toFormat('dd/MM (cccc)')
  : (dRaw || 'data solicitada');

// ── 8. DECISÃO PRINCIPAL ──────────────────────────────────────
let resultado, exactMatch = false;
const sugestoesHorarios = [];

// CAMINHO A — Data distante + NÃO insistiu
if (bloqueado) {
  const limiteData = agora.startOf('day').plus({ days: LIMITE_DIAS }).toFormat('yyyy-MM-dd');
  const opcoes = opcoesDoPeriodo(todosBlocos.filter(b => b.data <= limiteData));
  if (opcoes.length === 0) {
    resultado = `😕 Não há horários disponíveis nos próximos ${LIMITE_DIAS} dias.\n\nPosso verificar outra data?`;
  } else {
    opcoes.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
    resultado =
      `⚠️ A data que você pediu (*${dtLabel}*) está a *${Math.ceil(diffDias)} dias* de hoje.\n\n` +
      `Para garantir um atendimento mais rápido, separei os horários mais próximos:${PERIODO ? ' (período da ' + PERIODO_LABEL + ')' : ''}\n\n` +
      opcoes.map(fmtBloco).join('\n');
  }
}

// CAMINHO B — Data distante + insistiu
else if (diffDias > LIMITE_DIAS && insistiu) {
  const dataAlvo = dtSolicitado.toFormat('yyyy-MM-dd');
  const minSolicitado = (hRaw && hRaw !== '00:00') ? horaParaMin(hRaw) : -1;
  const blocosDoDia = todosBlocos.filter(b => b.data === dataAlvo);
  const blocoExato  = minSolicitado >= 0 ? blocosDoDia.find(b => b.minutos === minSolicitado) : null;

  if (blocoExato) {
    exactMatch = true;
    sugestoesHorarios.push(`${blocoExato.data} ${blocoExato.horario}`);
    resultado = `✅ Consegui o horário que você pediu!\n\n${fmtBloco(blocoExato)}\n\nConfirmo o agendamento?`;
  } else if (blocosDoDia.length === 0) {
    resultado = `😕 Não há horários disponíveis em *${dtLabel}*.\n\nPosso verificar um dia antes ou depois?`;
  } else {
    const opcoes = minSolicitado >= 0
      ? vizinhos(blocosDoDia, minSolicitado)
      : opcoesDoPeriodo(blocosDoDia, todosBlocos);
    opcoes.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
    const intro = minSolicitado >= 0
      ? `O horário das *${hRaw}* não está disponível em *${dtLabel}*, mas encontrei estas opções neste mesmo dia:`
      : `Encontrei estas opções em *${dtLabel}*:`;
    resultado = `${intro}\n\n` + opcoes.map(fmtBloco).join('\n') + `\n\nQual prefere? Ou verifico outro dia?`;
  }
}

// CAMINHOS C / D — Data normal (≤ limite de dias)
else {
  const dataAlvo = dtSolicitado?.isValid ? dtSolicitado.toFormat('yyyy-MM-dd') : null;
  const minSolicitado = (hRaw && hRaw !== '00:00') ? horaParaMin(hRaw) : -1;
  const blocosDoDia   = dataAlvo ? todosBlocos.filter(b => b.data === dataAlvo) : todosBlocos;
  const blocoExato    = (minSolicitado >= 0 && blocosDoDia.length > 0)
    ? blocosDoDia.find(b => b.minutos === minSolicitado) : null;

  if (blocoExato) {
    exactMatch = true;
    sugestoesHorarios.push(`${blocoExato.data} ${blocoExato.horario}`);
    resultado =
      `✅ Ótima notícia! O horário *${dtLabel} às ${blocoExato.horario}* está disponível ` +
      `com *${blocoExato.profNome}*.\n\nPosso confirmar sua avaliação?`;
  } else if (blocosDoDia.length === 0) {
    const opcoes = opcoesDoPeriodo(todosBlocos, todosBlocos);
    if (opcoes.length === 0) {
      resultado = `😕 Não há horários disponíveis no período consultado. Posso verificar outras datas?`;
    } else {
      opcoes.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
      const periodoInfo = PERIODO ? ` (período da ${PERIODO_LABEL})` : '';
      resultado =
        `😕 Não há horários disponíveis em *${dtLabel}*.\n\nEncontrei estas opções nos próximos dias${periodoInfo}:\n\n` +
        opcoes.map(fmtBloco).join('\n') + `\n\nQual desses fica melhor para você?`;
    }
  } else {
    const opcoes = minSolicitado >= 0
      ? vizinhos(blocosDoDia, minSolicitado)
      : opcoesDoPeriodo(blocosDoDia, todosBlocos);
    opcoes.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
    const intro = minSolicitado >= 0
      ? `O horário das *${hRaw}* não está disponível para *${dtLabel}*, mas tenho estas opções:`
      : (dataAlvo
        ? `Encontrei os seguintes horários disponíveis para *${dtLabel}*${PERIODO ? ' (período da ' + PERIODO_LABEL + ')' : ''}:`
        : `Encontrei os seguintes horários disponíveis${PERIODO ? ' (período da ' + PERIODO_LABEL + ')' : ''}:`);
    resultado = `📅 ${intro}\n\n` + opcoes.map(fmtBloco).join('\n') + `\n\nQual desses fica melhor para você?`;
  }
}

// ── 9. OUTPUT — hard cap de 2 ─────────────────────────────────
// Garante nunca mais de 2 sugestões, independente do caminho
const sugestoesFinal = sugestoesHorarios.slice(0, 2);

return {
  json: {
    resultado,
    sugestoes_horarios:      sugestoesFinal,
    periodo_solicitado:      PERIODO ? PERIODO_LABEL : 'sem preferência',
    data_distante_bloqueada: bloqueado,
    exact_match:             exactMatch,
    diff_dias:               Math.ceil(diffDias),
    total_dias_api:          diasAPI.length,
    total_blocos_validos:    todosBlocos.length,
    usando_fallback:         usandoFallback
  }
};

// ── Validar Slot Agendar — Yamar (com Profissional Fallback) ─────────
let d = {};
try { d = $('Configuracao Unidades').first().json; } catch(e) { d = $input.item.json; }

const PROF_PRINCIPAL = { id: String(d.config_agenda?.profissional?.id || ''),          nome: d.config_agenda?.profissional?.nome || 'Profissional' };
const PROF_FALLBACK  = { id: String(d.config_agenda?.profissional_fallback?.id || ''), nome: d.config_agenda?.profissional_fallback?.nome || '' };

const inputItems    = $input.all().map(i => i.json);
const isNovoFormato = inputItems.length > 0 && Array.isArray(inputItems[0].AvaliableTimes);

let slots = [];
if (isNovoFormato) {
  slots = (inputItems[0].AvaliableTimes || []).filter(s => s.isSelectable !== false);
} else {
  slots = inputItems;
}

const norm = h => {
  if (!h) return '';
  const p = h.toString().split(':');
  return p[0].padStart(2,'0') + ':' + (p[1]||'00').padStart(2,'0');
};

const hAlvo = norm(d.horario_agendado || '');

function buscarSlot(profId) {
  return slots.find(s => {
    const id   = String(isNovoFormato ? s.professionalId : s.ProfessionalId);
    const from = norm(isNovoFormato ? s.from : s.From);
    return id === profId && from === hAlvo;
  }) || null;
}

let v = { aprovado: false, motivo: 'Horário indisponível.' };
let idF = null, nomeF = '';

if (!slots.length) {
  v.motivo = 'Não há agenda aberta ou horários disponíveis neste dia.';
} else if (!hAlvo) {
  v.motivo = 'Horário solicitado não informado.';
} else {
  let slotEncontrado = buscarSlot(PROF_PRINCIPAL.id);
  if (slotEncontrado) {
    v = { aprovado: true, motivo: 'Horário disponível.' };
    idF = PROF_PRINCIPAL.id; nomeF = PROF_PRINCIPAL.nome;
  } else if (PROF_FALLBACK.id) {
    slotEncontrado = buscarSlot(PROF_FALLBACK.id);
    if (slotEncontrado) {
      v = { aprovado: true, motivo: 'Horário disponível.' };
      idF = PROF_FALLBACK.id; nomeF = PROF_FALLBACK.nome;
    }
  }
  if (!v.aprovado) {
    v.motivo = `O horário ${d.horario_agendado} não está disponível.`;
  }
}

return {
  json: {
    ...d,
    validacao:               v,
    id_profissional_final:   idF,
    nome_profissional_final: nomeF,
    hora_buscada:            hAlvo,
    slots_encontrados_total: slots.length
  }
};

